import functools,http.server as h
class R(h.SimpleHTTPRequestHandler):
  def go(s):
    if s.path in ('/','/index.html'):
      s.send_response(302);s.send_header('Location','/nyc-311-pileup/');s.send_header('Cache-Control','no-store');s.end_headers();return True
  def do_GET(s):
    s.go() or super().do_GET()
  def do_HEAD(s):
    s.go() or super().do_HEAD()
h.ThreadingHTTPServer(('127.0.0.1',8942),functools.partial(R,directory='/Users/joshgreenman/Experiments')).serve_forever()
